/* ==========================================================
   Modern Dark Bistro Theme - Shopping Cart Stylesheet
   ========================================================== */

/* Exact dark theme palette defined on :root and used everywhere */
:root {
    --bg-nav-footer: #181512;  /* Navbar and footer background */
    --bg-main: #241F1C;        /* Page background and cards */
    --accent-orange: #FF6B00;  /* Primary buttons, cart badge */
    --text-main: #FAF3E0;      /* Headings and body text */
    --accent-gold: #F59E0B;    /* Prices, icons, highlights */
    --status-green: #10B981;   /* Positive / available tags */
}

/* Base layout and page background */
body {
    background-color: var(--bg-main);
    color: var(--text-main);
    font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
}

main {
    flex: 1;
}

/* Navbar styling */
.bistro-navbar {
    background-color: var(--bg-nav-footer);
    border-bottom: 1px solid color-mix(in srgb, var(--accent-gold) 30%, transparent);
    padding-top: 0.85rem;
    padding-bottom: 0.85rem;
}

.brand-title {
    color: var(--accent-gold);
    letter-spacing: 0.5px;
}

.brand-title:hover,
.brand-title:focus {
    color: var(--text-main);
}

.bistro-navbar .nav-link {
    color: var(--text-main);
    font-weight: 500;
    transition: color 0.2s ease;
}

.bistro-navbar .nav-link:hover,
.bistro-navbar .nav-link:focus,
.bistro-navbar .nav-link.active {
    color: var(--accent-orange);
}

/* Cart counter badge in navbar */
.cart-badge {
    background-color: var(--accent-orange);
    color: var(--text-main);
}

/* Page Heading & Subtitle */
.spotlight-label {
    color: var(--accent-gold);
    font-weight: 600;
    font-size: 0.95rem;
    letter-spacing: 0.8px;
    text-transform: uppercase;
}

.page-heading {
    color: var(--text-main);
}

.hero-subtitle {
    color: var(--text-main);
    opacity: 0.85;
    max-width: 650px;
}

/* Cart Item Row Card */
.cart-item-row {
    background-color: var(--bg-main);
    color: var(--text-main);
    border: 1px solid color-mix(in srgb, var(--text-main) 18%, transparent);
    border-radius: 14px;
    padding: 1rem 1.25rem;
    transition: border-color 0.2s ease;
}

.cart-item-row:hover {
    border-color: var(--accent-gold);
}

.cart-item-img {
    width: 96px;
    height: 76px;
    object-fit: cover;
    border-radius: 10px;
    background-color: var(--bg-nav-footer);
    border: 1px solid color-mix(in srgb, var(--accent-gold) 30%, transparent);
}

.cart-item-name {
    color: var(--text-main);
    font-weight: 700;
}

.unit-price {
    color: var(--text-main);
    opacity: 0.8;
    font-size: 0.92rem;
}

.line-total {
    color: var(--accent-gold);
    font-weight: 700;
    font-size: 1.15rem;
}

/* Quantity Control (+/- buttons and number display) */
.qty-control {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    background-color: var(--bg-nav-footer);
    border: 1px solid color-mix(in srgb, var(--accent-gold) 35%, transparent);
    border-radius: 8px;
    padding: 0.25rem 0.5rem;
}

.btn-qty {
    background-color: var(--accent-orange);
    color: var(--text-main);
    border: none;
    width: 30px;
    height: 30px;
    border-radius: 6px;
    font-weight: 700;
    line-height: 1;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    transition: filter 0.2s ease;
}

.btn-qty:hover,
.btn-qty:focus {
    background-color: var(--accent-orange);
    color: var(--text-main);
    filter: brightness(0.9);
}

.qty-value {
    min-width: 26px;
    text-align: center;
    font-weight: 600;
    color: var(--text-main);
}

/* Inline quantity limit error message (min 1 / max 20) */
.qty-error {
    color: var(--accent-orange);
    font-size: 0.82rem;
    font-weight: 600;
    min-height: 1.2rem;
}

/* Remove Item Button */
.btn-remove {
    background-color: transparent;
    color: var(--accent-orange);
    border: 1px solid var(--accent-orange);
    font-weight: 600;
    font-size: 0.88rem;
    padding: 0.4rem 0.85rem;
    border-radius: 8px;
    transition: background-color 0.2s ease, color 0.2s ease;
}

.btn-remove:hover,
.btn-remove:focus {
    background-color: var(--accent-orange);
    color: var(--text-main);
}

/* Cart Summary Card */
.cart-summary-card {
    background-color: var(--bg-nav-footer);
    border: 1px solid color-mix(in srgb, var(--accent-gold) 35%, transparent);
    border-radius: 14px;
    padding: 1.5rem;
}

.summary-label {
    color: var(--text-main);
    opacity: 0.85;
}

.summary-total {
    color: var(--accent-gold);
    font-weight: 700;
    font-size: 1.35rem;
}

/* Primary & Secondary CTA Buttons */
.btn-bistro-primary {
    background-color: var(--accent-orange);
    color: var(--text-main);
    border: none;
    font-weight: 600;
    padding: 0.65rem 1.4rem;
    border-radius: 8px;
    text-decoration: none;
    transition: filter 0.2s ease;
}

.btn-bistro-primary:hover,
.btn-bistro-primary:focus {
    background-color: var(--accent-orange);
    color: var(--text-main);
    filter: brightness(0.9);
}

.btn-bistro-outline {
    background-color: transparent;
    color: var(--accent-gold);
    border: 1px solid var(--accent-gold);
    font-weight: 600;
    padding: 0.65rem 1.4rem;
    border-radius: 8px;
    text-decoration: none;
    transition: background-color 0.2s ease, color 0.2s ease;
}

.btn-bistro-outline:hover,
.btn-bistro-outline:focus {
    background-color: var(--accent-gold);
    color: var(--bg-nav-footer);
}

/* Empty Cart Card */
.empty-cart-box {
    background-color: var(--bg-nav-footer);
    border: 1px dashed color-mix(in srgb, var(--accent-gold) 45%, transparent);
    border-radius: 14px;
    padding: 3rem 1.5rem;
}

.empty-cart-title {
    color: var(--text-main);
}

.empty-cart-badge {
    color: var(--status-green);
    font-weight: 600;
    font-size: 0.9rem;
}

/* Footer styling */
.bistro-footer {
    background-color: var(--bg-nav-footer);
    border-top: 1px solid color-mix(in srgb, var(--accent-gold) 30%, transparent);
}

.footer-brand {
    color: var(--accent-gold);
}

.footer-text {
    color: var(--text-main);
    opacity: 0.78;
}

.footer-link {
    color: var(--text-main);
    text-decoration: none;
    font-size: 0.9rem;
    transition: color 0.2s ease;
}

.footer-link:hover {
    color: var(--accent-orange);
}

// ==========================================================
// The Flavour Lounge - Shopping Cart Logic
// ==========================================================

// Same localStorage key used by Special Deals and Menu pages
const CART_STORAGE_KEY = "flavourCart";
const MIN_QTY = 1;
const MAX_QTY = 20;

// Fallback SVG image used if an item does not have an image or fails to load
const FALLBACK_IMAGE = "data:image/svg+xml;charset=UTF-8," + encodeURIComponent(`
    <svg xmlns="http://www.w3.org/2000/svg" width="240" height="180" viewBox="0 0 240 180">
        <rect width="240" height="180" fill="#181512"/>
        <circle cx="120" cy="82" r="42" fill="#241F1C" stroke="#F59E0B" stroke-width="3"/>
        <text x="120" y="87" text-anchor="middle" fill="#F59E0B" font-family="Segoe UI, sans-serif" font-size="13" font-weight="bold">DISH</text>
        <text x="120" y="152" text-anchor="middle" fill="#FAF3E0" font-family="Segoe UI, sans-serif" font-size="12">The Flavour Lounge</text>
    </svg>
`);

// Safely read and parse the cart array from localStorage
function getCart() {
    try {
        const rawCart = localStorage.getItem(CART_STORAGE_KEY);
        if (!rawCart) {
            return [];
        }
        const parsed = JSON.parse(rawCart);
        return Array.isArray(parsed) ? parsed : [];
    } catch (error) {
        // Fall back to an empty array if JSON parsing fails
        return [];
    }
}

// Save the updated cart array back to localStorage
function saveCart(cart) {
    localStorage.setItem(CART_STORAGE_KEY, JSON.stringify(cart));
}

// Format a numeric price in Pakistani Rupees (e.g., Rs. 1,350)
function formatPrice(amount) {
    return "Rs. " + Number(amount).toLocaleString("en-PK");
}

// Escape HTML special characters so item names render safely
function escapeHtml(text) {
    return String(text)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;");
}

// Update the navbar Cart badge with the total item quantity
function updateCartBadge(cart) {
    const cartCountElement = document.getElementById("cartCount");
    const totalQty = cart.reduce(function (sum, item) {
        return sum + (Number(item.qty) || 0);
    }, 0);

    cartCountElement.textContent = totalQty;
}

// Show a small inline error message inside the row for invalid quantity limits
function showInlineQtyError(itemId, message) {
    const errorElement = document.querySelector(`.qty-error[data-error-id="${CSS.escape(itemId)}"]`);
    if (errorElement) {
        errorElement.textContent = message;
    }
}

// Change an item's quantity (+1 or -1) while enforcing the 1..20 limits
function changeQuantity(itemId, delta) {
    const cart = getCart();
    const item = cart.find(function (entry) {
        return String(entry.id) === String(itemId);
    });

    if (!item) {
        return;
    }

    const currentQty = Number(item.qty) || MIN_QTY;
    const nextQty = currentQty + delta;

    // Prevent going below 1
    if (nextQty < MIN_QTY) {
        showInlineQtyError(itemId, "Minimum quantity is 1.");
        return;
    }

    // Prevent going above 20
    if (nextQty > MAX_QTY) {
        showInlineQtyError(itemId, "Maximum quantity is 20.");
        return;
    }

    item.qty = nextQty;
    saveCart(cart);
    renderCart();
}

// Delete an item from the cart by id, save, and re-render
function removeItem(itemId) {
    const updatedCart = getCart().filter(function (entry) {
        return String(entry.id) !== String(itemId);
    });

    saveCart(updatedCart);
    renderCart();
}

// Render all cart rows (or the empty cart message) and sync the navbar badge
function renderCart() {
    const cartContainer = document.getElementById("cartContainer");
    const cart = getCart();

    // Always keep the navbar badge in sync
    updateCartBadge(cart);

    // Show empty state if there are no items in the cart
    if (cart.length === 0) {
        cartContainer.innerHTML = `
            <div class="empty-cart-box text-center mx-auto">
                <p class="empty-cart-badge mb-2">&#9733; Ready When You Are</p>
                <h2 class="h3 fw-bold empty-cart-title mb-3">Your cart is empty</h2>
                <p class="hero-subtitle mx-auto mb-4">
                    Explore our freshly prepared Pakistani dishes and chef's combo deals to start your order.
                </p>
                <div class="d-flex flex-wrap justify-content-center gap-3">
                    <a href="menu.html" class="btn btn-bistro-primary">Browse Menu</a>
                    <a href="special-deals.html" class="btn btn-bistro-outline">Browse Deals</a>
                </div>
            </div>
        `;
        return;
    }

    let grandTotal = 0;
    let totalItems = 0;
    let rowsHtml = "";

    // Build one row per cart item from JavaScript data
    cart.forEach(function (item) {
        const safeId = escapeHtml(item.id);
        const safeName = escapeHtml(item.name || "Menu Item");
        const unitPrice = Number(item.price) || 0;
        const qty = Number(item.qty) || 1;
        const lineTotal = unitPrice * qty;
        const imageSrc = item.image ? escapeHtml(item.image) : FALLBACK_IMAGE;

        grandTotal += lineTotal;
        totalItems += qty;

        rowsHtml += `
            <div class="cart-item-row mb-3" data-item-id="${safeId}">
                <div class="row align-items-center gy-3">
                    <!-- Item Image and Name -->
                    <div class="col-12 col-md-5 d-flex align-items-center gap-3">
                        <img
                            src="${imageSrc}"
                            alt="${safeName}"
                            class="cart-item-img"
                            onerror="this.onerror=null; this.src='${FALLBACK_IMAGE}';"
                        >
                        <div>
                            <h2 class="h6 cart-item-name mb-1">${safeName}</h2>
                            <p class="unit-price mb-0">Unit Price: ${formatPrice(unitPrice)}</p>
                        </div>
                    </div>

                    <!-- Quantity Minus / Plus Control -->
                    <div class="col-6 col-md-3 text-md-center">
                        <div class="qty-control" role="group" aria-label="Quantity for ${safeName}">
                            <button
                                type="button"
                                class="btn-qty btn-minus"
                                data-item-id="${safeId}"
                                aria-label="Decrease quantity of ${safeName}"
                            >-</button>
                            <span class="qty-value">${qty}</span>
                            <button
                                type="button"
                                class="btn-qty btn-plus"
                                data-item-id="${safeId}"
                                aria-label="Increase quantity of ${safeName}"
                            >+</button>
                        </div>
                        <div class="qty-error mt-1" data-error-id="${safeId}" role="alert"></div>
                    </div>

                    <!-- Line Total -->
                    <div class="col-3 col-md-2 text-md-end">
                        <span class="d-block small unit-price">Line Total</span>
                        <span class="line-total">${formatPrice(lineTotal)}</span>
                    </div>

                    <!-- Remove Button -->
                    <div class="col-3 col-md-2 text-end">
                        <button
                            type="button"
                            class="btn-remove"
                            data-item-id="${safeId}"
                        >Remove</button>
                    </div>
                </div>
            </div>
        `;
    });

    // Combine item rows with a simple Order Summary card
    cartContainer.innerHTML = `
        <div class="row g-4">
            <div class="col-lg-8">
                ${rowsHtml}
            </div>
            <div class="col-lg-4">
                <aside class="cart-summary-card">
                    <h2 class="h5 fw-bold mb-3">Cart Summary</h2>
                    <div class="d-flex justify-content-between mb-2">
                        <span class="summary-label">Total Items</span>
                        <span class="fw-semibold">${totalItems}</span>
                    </div>
                    <hr>
                    <div class="d-flex justify-content-between align-items-center mb-4">
                        <span class="fw-semibold">Grand Total</span>
                        <span class="summary-total">${formatPrice(grandTotal)}</span>
                    </div>
                    <div class="d-grid gap-2">
                        <a href="special-deals.html" class="btn btn-bistro-primary text-center">Browse Deals</a>
                        <a href="menu.html" class="btn btn-bistro-outline text-center">Browse Menu</a>
                    </div>
                </aside>
            </div>
        </div>
    `;
}

// Initialize cart page and attach click event listeners
document.addEventListener("DOMContentLoaded", function () {
    renderCart();

    const cartContainer = document.getElementById("cartContainer");

    // Event delegation for minus, plus, and remove buttons
    cartContainer.addEventListener("click", function (event) {
        const minusBtn = event.target.closest(".btn-minus");
        if (minusBtn) {
            changeQuantity(minusBtn.getAttribute("data-item-id"), -1);
            return;
        }

        const plusBtn = event.target.closest(".btn-plus");
        if (plusBtn) {
            changeQuantity(plusBtn.getAttribute("data-item-id"), 1);
            return;
        }

        const removeBtn = event.target.closest(".btn-remove");
        if (removeBtn) {
            removeItem(removeBtn.getAttribute("data-item-id"));
        }
    });
});

