        name: "Lahori Family Karahi Combo",
        items: "Full Chicken Makhni Karahi, 4 Fresh Roghni Naans, Kachumber Salad, and 1.5L Family Drink.",
        oldPrice: 3600,
        newPrice: 2880,
        category: "Combos",
        badge: "Available",
