/* ── Responsive helpers ─────────────────────────────────────────────────── */
/* Prevent any child from causing horizontal scroll at 360 px */
.deals-subtitle { max-width: 38rem; }

/* ── Category Filter Pills ───────────────────────────────────────────────── */
.filter-btn {
    background-color: var(--color-white);
    color: var(--color-maroon);
    border: 2px solid var(--color-cream-dark);
    border-radius: 50rem;
    /* min 44px touch target height */
    min-height: 44px;
    padding: 0.45rem 1.2rem;
    font-weight: 600;
    font-size: 0.92rem;
    transition: all var(--transition-base);
}

.filter-btn:hover,
.filter-btn:focus-visible,
.filter-btn.active {
    background-color: var(--color-orange);
    border-color: var(--color-orange);
    color: var(--color-white);
}

/* Explicit visible focus ring for keyboard users */
.filter-btn:focus-visible {
    outline: 3px solid var(--color-orange);
    outline-offset: 3px;
}

/* ── Deal Cards ──────────────────────────────────────────────────────────── */
.deal-card {
    background-color: var(--color-white);
    border: 1px solid color-mix(in srgb, var(--color-maroon) 12%, transparent);
    border-radius: var(--radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-soft);
    transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.deal-card:hover {
    transform: translateY(-6px);
    box-shadow: var(--shadow-card);
}

.deal-img-wrapper {
    position: relative;
    background-color: var(--color-cream-dark);
}

.deal-img {
    width: 100%;
    height: 200px;
    object-fit: cover;
    display: block;
    /* fallback background while SVG loads */
    background-color: var(--color-cream-dark);
}

/* Discount Percentage Badge */
.discount-badge {
    position: absolute;
    top: 12px;
    right: 12px;
    background-color: var(--color-orange);
    color: var(--color-white);
    font-weight: 700;
    font-size: 0.82rem;
    padding: 0.35rem 0.75rem;
    border-radius: 50rem;
}

/* Category Label & Star Rating */
.category-tag {
    color: var(--color-orange);
    font-size: 0.82rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.star-rating {
    color: var(--color-orange);
    font-size: 0.88rem;
    font-weight: 600;
}

/* Availability Badge */
.status-badge {
    background-color: var(--color-cream);
    color: var(--color-maroon);
    border: 1px solid color-mix(in srgb, var(--color-maroon) 20%, transparent);
    font-size: 0.75rem;
    font-weight: 600;
    padding: 0.25rem 0.65rem;
    border-radius: 50rem;
}

.deal-title { color: var(--color-maroon); }

.deal-items {
    color: var(--color-text-muted);
    font-size: 0.94rem;
}

/* Price Display */
.old-price {
    color: var(--color-text-muted);
    text-decoration: line-through;
    font-size: 0.92rem;
}

.new-price {
    color: var(--color-maroon);
    font-family: var(--font-heading);
    font-size: 1.35rem;
    font-weight: 700;
}

/* "Add to Cart" button – 44px min touch target, visible focus */
.btn-add-deal {
    min-height: 44px;
}

.btn-add-deal:focus-visible,
.btn-flavour-primary:focus-visible,
.btn-flavour-outline:focus-visible,
.btn-flavour-maroon:focus-visible {
    outline: 3px solid var(--color-orange);
    outline-offset: 3px;
}

/* Empty Filter Message */
.empty-deals-msg {
    color: var(--color-maroon);
    font-weight: 600;
    font-size: 1.05rem;
    padding: 2.25rem 1rem;
    border: 1px dashed color-mix(in srgb, var(--color-maroon) 35%, transparent);
    border-radius: var(--radius-lg);
    background-color: var(--color-white);
}

/* Bootstrap Toast */
.flavour-toast {
    background-color: var(--color-maroon);
